CREATE OR REPLACE FUNCTION public.migrate_embeddings()
 RETURNS void
 LANGUAGE plpgsql
AS $function$
    DECLARE
        r RECORD;
        count_processed INTEGER := 0;
    BEGIN
        -- Add dimensions column if it doesn't exist
        IF NOT EXISTS (
            SELECT 1 FROM information_schema.columns 
            WHERE table_name = 'chunk_embeddings' AND column_name = 'dimensions'
        ) THEN
            ALTER TABLE chunk_embeddings ADD COLUMN dimensions INTEGER DEFAULT 1024;
            UPDATE chunk_embeddings SET dimensions = 1024;
        END IF;

        -- Process each embedding from chunk_embeddings_small
        FOR r IN SELECT chunk_id, model, embedding, created_at FROM chunk_embeddings_small
        LOOP
            -- Insert into chunk_embeddings
            BEGIN
                INSERT INTO chunk_embeddings (chunk_id, model, embedding, dimensions, created_at)
                VALUES (r.chunk_id, r.model, r.embedding, 384, r.created_at)
                ON CONFLICT (chunk_id, model) DO UPDATE
                SET dimensions = 384, created_at = r.created_at;

                count_processed := count_processed + 1;

                -- Log progress every 100 embeddings
                IF count_processed % 100 = 0 THEN
                    RAISE NOTICE 'Processed % embeddings', count_processed;
                END IF;
            EXCEPTION
                WHEN OTHERS THEN
                    RAISE NOTICE 'Error processing chunk %: %', r.chunk_id, SQLERRM;
            END;
        END LOOP;

        RAISE NOTICE 'Successfully processed % embeddings', count_processed;
    END;
    $function$

CREATE OR REPLACE FUNCTION public.pad_vector_384_to_1024(v vector)
 RETURNS double precision[]
 LANGUAGE plpgsql
AS $function$
DECLARE
    result float8[] := '{0}'::float8[];
    v_array float8[] := v::float8[];
    i integer;
BEGIN
    -- Resize array to 1024 (starts with a single zero)
    FOR i IN 2..1024 LOOP
        result := array_append(result, 0::float8);
    END LOOP;

    -- Copy first 384 elements from input vector
    FOR i IN 1..384 LOOP
        result[i] := v_array[i];
    END LOOP;

    RETURN result;
END;
$function$

CREATE OR REPLACE FUNCTION public.pad_vector_to_1024(v vector)
 RETURNS vector
 LANGUAGE plpgsql
AS $function$
DECLARE
    padded vector(1024);
    v_array float8[];
    i integer;
BEGIN
    -- Convert the vector to an array
    v_array := array(SELECT unnest(v::float8[]));

    -- Create a zero vector of 1024 dimensions
    padded := '{0}'::float8[]::vector(1024);

    -- Copy the 384 values from v into the first 384 positions of padded
    FOR i IN 1..384 LOOP
        -- Use array indexing to set values
        padded[i] := v_array[i];
    END LOOP;

    RETURN padded;
END;
$function$
